p='src/server/services/search-service.ts'
s=open(p).read()

start=s.index('export async function indexIssue')
end=s.index('function hrefFor')
new='''/**
 * The three index writers own the "is this searchable?" decision: a project is
 * indexed while it is live, an issue while it and its project are live, a
 * comment while it, its issue and that issue's project are live. A subject
 * that fails the rule has its document removed instead, so callers can hand
 * over any row without checking it first.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, issue.projectId);

  if (isArchived(issue) || project === null || isArchived(project)) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  const project =
    issue === null
      ? null
      : await projectRepo.findProjectById(orgId, issue.projectId);

  if (
    isArchived(comment) ||
    issue === null ||
    isArchived(issue) ||
    project === null ||
    isArchived(project)
  ) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (isArchived(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Re-indexes every live issue of one project, and the live comments on them,
 * walking each list to its end. Used when a project comes back (its kept
 * content was unindexed while it was archived) and by the rebuild job. Issues
 * that stayed archived are skipped, so they and their comments stay hidden.
 */
export async function indexProjectContent(
  orgId: OrgId,
  projectId: ProjectId,
  onIndexed?: () => void,
): Promise<void> {
  let issueCursor: string | null = null;
  do {
    const page: Page<Issue> = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: CONTENT_PAGE_SIZE,
      cursor: issueCursor,
    });
    for (const issue of page.items) {
      await indexIssue(orgId, issue);
      onIndexed?.();
    }
    issueCursor = page.nextCursor;
  } while (issueCursor !== null);

  let afterId: CommentId | null = null;
  for (;;) {
    const batch: readonly Comment[] = await commentRepo.listLiveCommentsForProject(
      orgId,
      projectId,
      afterId,
      CONTENT_PAGE_SIZE,
    );
    for (const comment of batch) {
      await indexComment(orgId, comment);
      onIndexed?.();
    }
    const last = batch.at(-1);
    if (last === undefined || batch.length < CONTENT_PAGE_SIZE) break;
    afterId = last.id;
  }
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const reindexIssue = async (orgId: OrgId, issueId: IssueId) => {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (issue) await indexIssue(orgId, issue);
    else await removeFromIndex(orgId, "issue", issueId);
  };
  const reindexComment = async (orgId: OrgId, commentId: CommentId) => {
    const comment = await commentRepo.findCommentById(orgId, commentId);
    if (comment) await indexComment(orgId, comment);
    else await removeFromIndex(orgId, "comment", commentId);
  };
  const reindexProject = async (orgId: OrgId, projectId: ProjectId) => {
    const project = await projectRepo.findProjectById(orgId, projectId);
    if (project) await indexProject(orgId, project);
    else await removeFromIndex(orgId, "project", projectId);
  };

  const offs: Unsubscribe[] = [
    subscribe("issue.created", (payload) =>
      reindexIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.updated", (payload) =>
      reindexIssue(payload.orgId, payload.issueId),
    ),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
      await searchRepo.deleteCommentDocumentsForIssue(
        payload.orgId,
        payload.issueId,
      );
    }),
    subscribe("comment.created", (payload) =>
      reindexComment(payload.orgId, payload.commentId),
    ),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", (payload) =>
      reindexProject(payload.orgId, payload.projectId),
    ),
    subscribe("project.archived", async (payload) => {
      await searchRepo.deleteSearchDocumentsForProject(
        payload.orgId,
        payload.projectId,
      );
    }),
    subscribe("project.restored", async (payload) => {
      await reindexProject(payload.orgId, payload.projectId);
      await indexProjectContent(payload.orgId, payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      switch (payload.subjectKind) {
        case "issue":
          return reindexIssue(payload.orgId, payload.subjectId as IssueId);
        case "comment":
          return reindexComment(payload.orgId, payload.subjectId as CommentId);
        case "project":
          return reindexProject(payload.orgId, payload.subjectId as ProjectId);
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

