/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexProject,
  indexProjectContent,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";
import type { Page } from "@/types/common";
import type { Project } from "@/types/project";

/** Rows read per page while walking the org's projects. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects and, inside each, its live issues and
 * comments, re-upserting every document; then prunes whatever the index still
 * holds for the tenant that the searchability rule does not allow (archived or
 * deleted subjects, duplicates). Scoped to a single org on purpose: a
 * full-fleet reindex is a sequence of these, so one slow tenant cannot stall
 * the rest, and no other tenant's documents are read or removed.
 *
 * Archived rows are never walked: an archived project hides everything under
 * it, an archived issue hides its comments, and the index writers would remove
 * their documents anyway. Every list is followed to its last page, so the
 * rebuild covers the whole workspace however large it is.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    let cursor: string | null = null;

    do {
      const page: Page<Project> = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
      });

      for (const project of page.items) {
        try {
          await indexProject(orgId, project);
          result.processed += 1;

          await indexProjectContent(orgId, project.id, () => {
            result.processed += 1;
          });
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      cursor = page.nextCursor;
    } while (cursor !== null);

    try {
      await searchRepo.pruneSearchDocuments(orgId);
    } catch (error) {
      result.failed += 1;
      logger.error("failed to prune search index", {
        orgId,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  });
}
