    const result = await runSearchReindexJob(tenant.org.id);
    expect(result.failed).toBe(0);

    // 1 project + 230 issues + 230 comments.
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(461);
    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Hotel5",
